create function public.search_community_recipes(p_term text default '',p_category text default null,p_minutes integer default null,p_mine boolean default false,p_offset integer default 0) returns setof public.community_recipes language sql stable security invoker set search_path=public set statement_timeout='5s' as $$ select r.* from public.community_recipes r where (case when p_mine then r.user_id=(select auth.uid()) else r.published end) and (p_category is null or r.category=p_category) and (p_minutes is null or r.minutes<=p_minutes) and (coalesce(btrim(p_term),'')='' or r.title ilike '%'||left(p_term,100)||'%' or r.description ilike '%'||left(p_term,100)||'%' or exists(select 1 from unnest(r.ingredients) i where i ilike '%'||left(p_term,100)||'%')) order by r.created_at desc,r.id limit 12 offset greatest(0,least(coalesce(p_offset,0),12000)) $$; revoke all on function public.search_community_recipes(text,text,integer,boolean,integer) from public; grant execute on function public.search_community_recipes(text,text,integer,boolean,integer) to anon,authenticated;
